#include <iostream>
#include <string>

int main()
{
    std::string line{};
    if (!std::getline(std::cin, line)) return 0;

    std::string result{};

    for (std::size_t i = line.size(); i > 0; --i)
    {
        result += line[i - 1];
    }

    std::cout << result << "\n";

    return 0;
}
